RefPtr<HTMLElement> HTMLElementFactory::createKnownElement(const AtomString& localName, Document& document, bool createdByParser)
{
    return createKnownElement(tagNameForElementName(findHTMLElementName(localName)), document, createdByParser);
}

RefPtr<HTMLElement> HTMLElementFactory::createKnownElement(const QualifiedName& name, Document& document, bool createdByParser)
{
    return createKnownElementWithName(tagNameForElementName(name.nodeName()), name, document, createdByParser);
}

Ref<HTMLElement> HTMLElementFactory::createElement(const AtomString& localName, Document& document, bool createdByParser)
{
    auto elementName = findHTMLElementName(localName);
    if (elementName != ElementName::Unknown)
        return createKnownElement(tagNameForElementName(elementName), document, createdByParser).releaseNonNull();
    return HTMLUnknownElement::create(QualifiedName(nullAtom(), localName, HTMLNames::xhtmlNamespaceURI), document);
}

Ref<HTMLElement> HTMLElementFactory::createElement(const QualifiedName& name, Document& document, bool createdByParser)
{
    auto elementName = name.nodeName();
    if (elementName != ElementName::Unknown) {
        if (auto result = createKnownElementWithName(tagNameForElementName(elementName), name, document, createdByParser))
            return result.releaseNonNull();
    }
    return HTMLUnknownElement::create(name, document);
}

